package com.pcguard.agent.service;

import com.pcguard.agent.model.*; import java.time.*; import java.time.format.*; import java.util.*;
public final class ConsoleDashboard {
 private static final DateTimeFormatter CLOCK=DateTimeFormatter.ofPattern("HH:mm:ss").withZone(ZoneId.systemDefault()); private ConsoleDashboard(){}
 public static String render(String version,Snapshot s,List<Fault> faults,boolean backend){StringBuilder out=new StringBuilder("\n============================================================\nPC GUARD AGENT ").append(version).append("\n============================================================\nComputer : ").append(s.identity().get("hostname")).append("\nAgent ID : ").append(s.identity().get("computerId")).append("\nOS       : ").append(s.identity().get("osName")).append("\nStatus   : RUNNING\nBackend  : ").append(backend?"ONLINE":"OFFLINE").append("\n------------------\n"); section(out,"CPU","Usage",number(s.cpu(),"usagePercent"),"%",faults,"CPU");section(out,"MEMORY","Usage",number(s.memory(),"usagePercent"),"%",faults,"MEMORY");out.append("STORAGE\n");for(Map<String,Object>d:s.storage())out.append(d.get("mount")).append(" Usage    : ").append(value(number(d,"usagePercent"),"%")).append("\n");out.append("Status   : ").append(status(faults,"STORAGE",!s.storage().isEmpty())).append("\nTEMPERATURE\nCPU      : ").append(value(number(s.sensors(),"cpuTemperatureCelsius"),"°C")).append("\nStatus   : ").append(status(faults,"TEMPERATURE",number(s.sensors(),"cpuTemperatureCelsius")!=null)).append("\nNETWORK\nStatus   : ").append(s.network().stream().anyMatch(n->Boolean.TRUE.equals(n.get("up")))?"CONNECTED":"DISCONNECTED").append("\nACTIVE FAULTS\n");if(faults.isEmpty())out.append("None\n");else faults.forEach(f->out.append(f.severity()).append(" ").append(f.faultCode()).append(" — ").append(f.message()).append("\n"));return out.append("# Last update: ").append(CLOCK.format(s.timestamp())).append("\n").toString();}
 private static void section(StringBuilder out,String section,String label,Double value,String unit,List<Fault> faults,String category){out.append(section).append("\n").append(label).append("    : ").append(value(value,unit)).append("\nStatus   : ").append(status(faults,category,value!=null)).append("\n");} private static String status(List<Fault> faults,String category,boolean available){if(!available)return "UNKNOWN";return faults.stream().filter(f->f.category().name().equals(category)).map(f->f.severity().name()).findFirst().orElse("HEALTHY");} private static String value(Double number,String unit){return number==null?"UNKNOWN":String.format("%.1f%s",number,unit);}private static Double number(Map<String,Object> map,String key){Object value=map.get(key);return value instanceof Number number?number.doubleValue():null;}
}
